import{_ as e,o as a,c as o,ah as i}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Full demo and activity log","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/demo-et-journal.md","filePath":"src/en/guide/admin/demo-et-journal.md"}'),n={name:"en/guide/admin/demo-et-journal.md"};function r(s,t,d,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="full-demo-and-activity-log" tabindex="-1">Full demo and activity log <a class="header-anchor" href="#full-demo-and-activity-log" aria-label="Permalink to &quot;Full demo and activity log&quot;">​</a></h1><p>This page groups two administrator features that have nothing to do with each other: activating a full, free demo of ERA, and reviewing the history of actions taken in the application.</p><h2 id="activate-the-full-demo" tabindex="-1">Activate the full demo <a class="header-anchor" href="#activate-the-full-demo" aria-label="Permalink to &quot;Activate the full demo&quot;">​</a></h2><p><strong>This feature only appears if your school signed up online on Era Admission and is still on the free tier</strong> — that is, using ERA only for its admissions application queue, without a license for the rest of the application. If your school already has an active license (or is already in a demo period), you won&#39;t see this button.</p><p>When available, the offer appears on the <strong>Dashboard</strong>:</p><ol><li>Click <strong>Activate the demo</strong>.</li><li>A dialog summarizes how many days every ERA pôle will be unlocked with no commitment.</li><li>Click <strong>Activate demo</strong> to confirm.</li></ol><p>Once activated, a banner on the dashboard shows how many days are left, then warns you as the end approaches. After that period, the school returns to the free ERA Admissions tier: the application form keeps working, the other modules lock, and nothing is deleted — what you entered during the demo comes back as soon as you purchase a license. A banner on the dashboard says so. The demo can only be activated once.</p><h2 id="review-the-activity-log" tabindex="-1">Review the activity log <a class="header-anchor" href="#review-the-activity-log" aria-label="Permalink to &quot;Review the activity log&quot;">​</a></h2><p><strong>Activity Log</strong> (in the menu&#39;s <strong>Administration</strong> group) is a history of who created, updated, or deleted what in the application, and when.</p><p>You can filter the list by:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Detail</th></tr></thead><tbody><tr><td>Actor</td><td>search by the name or email of the person behind the action</td></tr><tr><td>Entity</td><td>the type of record involved (student, class, payment...)</td></tr><tr><td>Action</td><td>Created, Updated, Deleted, or Viewed</td></tr><tr><td>Date</td><td>a &quot;from&quot; / &quot;to&quot; range</td></tr></tbody></table><p>The <strong>Viewed</strong> action records staff reads of sensitive data:</p><ul><li>the confidential documents of <a href="/era-guide/en/guide/gestion-documentaire/">document management</a>, each time one is opened;</li><li><strong>grades</strong>: class or subject summaries and their exports, an evaluation&#39;s grade entry, results, higher-education grades and transcripts;</li><li><strong>bulletins</strong>: a class&#39;s bulletin list and each download;</li><li><strong>infirmary visits</strong>: the list and each visit opened.</li></ul><p>Each row says who looked at what and when; the detail gives the page opened (and, for a list, the search made). Parents and students viewing their own bulletins are not recorded.</p><p>Click <strong>View details</strong> on a row to show, in a dialog, the technical detail of the fields changed by that action.</p><p>One important limitation to know: changes to many-to-many relationships (for example attaching a guardian to a student, or assigning a role to a user) are <strong>not</strong> captured in this log — only the direct creation, update, or deletion of a record appears here.</p>',16)])])}const g=e(n,[["render",r]]);export{p as __pageData,g as default};
